588	/// Get the possible values for completion
589	fn possible_values(
590	    a: &clap::Arg,
591	) -> Option<Box<dyn Iterator<Item = clap::builder::PossibleValue> + '_>> {
592	    if !a.get_num_args().expect("built").takes_values() {
593	        None
594	    } else {
595	        a.get_value_parser().possible_values()
596	    }
597	}
